  /**
   * Resolve a branch-preferred snake_case element ID with a legacy camelCase fallback.
   *
   * @param {string} pstrId Preferred snake_case DOM id.
   * @returns {HTMLElement|null} Matching DOM node when available.
   */
  function fnGetCompatElementById(pstrId) {
    if (!pstrId) return null;
    var objElement = document.getElementById(pstrId);
    if (objElement) return objElement;
    var strLegacyId = pstrId.replace(
      /_([a-z])/g,
      function (pstrMatch, pstrLetter) {
        return pstrLetter.toUpperCase();
      },
    );
    if (strLegacyId === pstrId) return null;
    return document.getElementById(strLegacyId);
  }

