      hoverTransitionItems: [],
      activeTransition: "",
      activeTransitionItems: [],
      transform: "",
      transformItems: [],
      hoverTransform: "",
      hoverTransformItems: [],
      activeTransform: "",
      activeTransformItems: [],
      bgImage: "",
